insert into jobs (title, org, type, province, description, url, cta, tags, closing, status) values
  ('SAYouth.mobi', 'SAYouth', 'Job platform', 'National', 'A free, mobile-friendly platform where young South Africans can find jobs, learnerships, internships and short courses, and build a profile that employers can see.', 'https://sayouth.mobi/', null, ARRAY['youth','learnership','internship','free']::text[], null, 'published'),
  ('Youth Employment Service (YES)', 'YES', 'Youth programme', 'National', 'Year-long paid work experience placements with participating companies for young South Africans aged 18 to 35. Sign up and get matched.', 'https://www.yes4youth.co.za/', null, ARRAY['work experience','youth','placement']::text[], null, 'published'),
  ('Harambee Youth Employment Accelerator', 'Harambee', 'Youth programme', 'National', 'Connects young job-seekers to entry-level work opportunities and offers free work-readiness support before you apply.', 'https://www.harambee.co.za/', null, ARRAY['youth','entry level','work readiness']::text[], null, 'published'),
  ('Public Service Vacancy Circular', 'Department of Public Service and Administration', 'Government', 'National', 'The official, regularly updated list of vacancies across national and provincial government departments. Check the closing date on each post.', 'https://www.dpsa.gov.za/', null, ARRAY['government','public service','vacancies']::text[], null, 'published'),
  ('NYDA programmes and support', 'National Youth Development Agency', 'Youth programme', 'National', 'Youth development programmes, including skills training, business support and grants. Look for your nearest NYDA branch.', 'https://www.nyda.gov.za/', null, ARRAY['youth','grants','skills','business']::text[], null, 'published'),
  ('LinkedIn Jobs', 'LinkedIn', 'Job platform', 'National', 'One of the most active platforms for professional roles in South Africa. Set a job alert for your target title so new roles come to you.', 'https://www.linkedin.com/jobs', null, ARRAY['jobs','alerts','professional']::text[], null, 'published'),
  ('Indeed South Africa', 'Indeed', 'Job platform', 'National', 'A large general job board covering roles in every industry, with company reviews and salary information.', 'https://za.indeed.com/', null, ARRAY['jobs','all industries']::text[], null, 'published'),
  ('PNet', 'PNet', 'Job platform', 'National', 'A long-standing South African job board with listings from direct employers and recruitment agencies.', 'https://www.pnet.co.za/', null, ARRAY['jobs','recruiters']::text[], null, 'published');
